import numpy as np
q=np.array([0,.3,0,-1.57079,0,2,-.7853])
def rx(a):return np.array([[1,0,0],[0,np.cos(a),-np.sin(a)],[0,np.sin(a),np.cos(a)]])
def ry(a):return np.array([[np.cos(a),0,np.sin(a)],[0,1,0],[-np.sin(a),0,np.cos(a)]])
def rz(a):return np.array([[np.cos(a),-np.sin(a),0],[np.sin(a),np.cos(a),0],[0,0,1]])
def T(xyz=(0,0,0),R=np.eye(3)):
 t=np.eye(4);t[:3,:3]=R;t[:3,3]=xyz;return t
orig=[((0,0,.333),(0,0,0)),((0,0,0),(-np.pi/2,0,0)),((0,-.316,0),(np.pi/2,0,0)),((.0825,0,0),(np.pi/2,0,0)),((-.0825,.384,0),(-np.pi/2,0,0)),((0,0,0),(np.pi/2,0,0)),((.088,0,0),(np.pi/2,0,0))]
M=np.eye(4)
for i,(xyz,rpy) in enumerate(orig):
 M=M@T(xyz,rx(rpy[0])@ry(rpy[1])@rz(rpy[2]))@T(R=rz(q[i]))
 print(i+1, M[:3,3], 'zaxis',M[:3,2])
print('flange',M@T((0,0,.107)))
for z in [.0,.05,.1,.15]:
 x=(M@T((0,0,.107+z)))[:3,3]
 print('tcp local z',z, x)
