 m=(dd<2.5)&~green&(np.min(c,axis=2)<225)
 yy,xx=np.where(m); print('\n',cam,'n',len(xx),'bbox', (xx.min()+x0,yy.min()+y0,xx.max()+x0,yy.max()+y0) if len(xx) else None)
